1	@define-color primary #7fd0ff;
2	@define-color primary-container #004c6a;
3	@define-color outline #919191;
4	
5	* {
6	    font-family: "JetBrainsMono Nerd Font";
7	    font-size: 16px;
8	    background: none;
9	}
10	
11	window#waybar {
12	    background: transparent;
13	}
14	
15	
16	.modules-left,
17	.modules-center,
18	.modules-right{
19	    background: @primary-container;
20	    border: 2px solid @outline;
21	    border-radius: 10px;
22	    /* 4px, not 6px: the 26px sprites need the vertical room, and this keeps the
23	       bar at 56px — the height it already rendered at before the sprites moved
24	       into CSS. Raising it to 6px forces the bar to 60px. */
25	    margin: 4px 4px;
26	    padding: 4px 12px;
27	}
28	
29	/* A bit more breathing room on the right of the center pill. When the active
30	   workspace has no windows, the workspace numbers are the rightmost content, so
31	   this widens the gap between the last number and the pill's right edge — the
32	   no-tabs state reads as a deliberate, roomy inset. Raise/lower 24px to taste. */
33	.modules-center {
34	    padding-right: 24px;
35	}
36	
37	/* Every workspace button reserves the exact box the active one uses — same
38	   padding, margin, min size, and a same-width *transparent* border. Without
39	   this, only the active button carries a 1px border, so it is taller than the
40	   inactive buttons; the bar height tracks its tallest child, so the whole bar
41	   jumps up and down as the pokeball (active button) appears/moves. Reserving
42	   the border space up front keeps every button one fixed height.
43	   :not(.taskbar) keeps this off the taskbar module's buttons. */
44	#workspaces:not(.taskbar) button {
45	    padding: 4px 4px;
46	    margin: 4px 0px;
47	    min-width: 20px;
48	    min-height: 20px;
49	    border: 1px solid transparent;
50	    border-radius: 10px;
51	}
52	
53	/* :not(.taskbar) keeps this off the taskbar module's active button */
54	#workspaces:not(.taskbar) button.active {
55	    background-image: url('/home/krubics/.config/waybar/assets/pokeball.png');
56	    background-position: center;
57	    background-repeat: no-repeat;
58	    background-size: contain;
59	    background-origin: content-box; /* inset the ball from the accent pill's edges */
60	    background-color: @primary;
61	    color: transparent; /* hides the workspace number behind the pokeball */
62	    padding: 4px 4px;
63	    margin: 4px 0px;
64	    min-width: 20px;
65	    min-height: 20px;
66	    border: 1px solid @outline;
67	    border-radius: 10px;
68	}
69	
70	/* Shared geometry for every sprite. The PNGs are alpha-trimmed (originals in
71	   assets/original/), so the sprite's ink fills its canvas and the box size is
72	   the pokemon size. background-size: contain fits the sprite inside the box,
73	   so height lands on 26px only where min-width >= 26 * aspect ratio; wooper is
74	   the widest of the square-ish icons at 1.167:1, needing 30.33px, so 32px
75	   clears all three. */
76	#custom-clock-icon,
77	#network.icon,
78	#bluetooth.icon,
79	#custom-battery-icon {
80	    background-position: center;
81	    background-repeat: no-repeat;
82	    background-size: contain;
83	    background-origin: content-box;
84	    color: transparent; /* hides the placeholder space glyph */
85	    min-width: 22px;
86	    min-height: 20px;
87	    padding: 2px;
88	    margin: 4px 0;
89	}
90	
91	#custom-clock-icon { background-image: url('/home/krubics/.config/waybar/assets/dialga.png'); }
92	#network.icon      { background-image: url('/home/krubics/.config/waybar/assets/wooper.png'); }
93	#bluetooth.icon    { background-image: url('/home/krubics/.config/waybar/assets/magneton.png'); }
94	
95	/* A 5-cell gauge, not one pikachu: 629x126, so 26 * 4.992 = 130px of width */
96	#custom-battery-icon { min-width: 110px; }
97	
98	#custom-battery-icon.p100 { background-image: url('/home/krubics/.config/waybar/assets/pikachu-100.png'); }
99	#custom-battery-icon.p80  { background-image: url('/home/krubics/.config/waybar/assets/pikachu-80.png'); }
100	#custom-battery-icon.p60  { background-image: url('/home/krubics/.config/waybar/assets/pikachu-60.png'); }
101	#custom-battery-icon.p40  { background-image: url('/home/krubics/.config/waybar/assets/pikachu-40.png'); }
102	#custom-battery-icon.p20  { background-image: url('/home/krubics/.config/waybar/assets/pikachu-20.png'); }
103	#custom-battery-icon.p10  { background-image: url('/home/krubics/.config/waybar/assets/pikachu-10.png'); }
104	
105	#custom-taskbar-divider,
106	#custom-divider {
107	    color: @outline;
108	    margin: 0 6px;
109	}
110	
111	#workspaces.taskbar button {
112	    min-width: 0;
113	    min-height: 0;
114	    padding: 0;
115	    margin: 0;
116	    border: none;
117	    background: transparent;
118	}
119	
120	#workspaces.taskbar .taskbar-window {
121	    padding: 2px 4px;
122	    margin: 0 2px;
123	    border-radius: 5px;
124	}
125	
126	#workspaces.taskbar .taskbar-window:hover {
127	    background: @primary-container
128	}
129

